SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_37d79d4f87ca0275>
    <urn:graphragprov:unit:u_84b9f0bec0f3cce0>
    <urn:graphragprov:unit:u_b231efe3553443f9>
    <urn:graphragprov:unit:u_c6a596d02fbf1cbf>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
